#![cfg_attr(not(feature = "rt"), allow(dead_code))]

//! Signal driver

use crate::io::driver::{Driver as IoDriver, Interest};
use crate::io::PollEvented;
use crate::park::Park;
use crate::signal::registry::{globals, EventId};
use crate::sync::watch;

use mio::net::UnixStream;
use std::io::{self, Read};
use std::ptr;
use std::sync::atomic::Ordering;
use std::sync::{Arc, Weak};
use std::task::{Context, Poll, RawWaker, RawWakerVTable, Waker};
use std::time::Duration;

/// Responsible for registering wakeups when an OS signal is received, and
/// subsequently dispatching notifications to any signal listeners as appropriate.
///
/// Note: this driver relies on having an enabled IO driver in order to listen to
/// pipe write wakeups.
#[derive(Debug)]
pub(crate) struct Driver {
    /// Thread parker. The `Driver` park implementation delegates to this.
    park: IoDriver,

    /// A pipe for receiving wake events from the signal handler
    receiver: PollEvented<UnixStream>,

    /// Shared state
    inner: Arc<Inner>,
    pipe_drain_budget: u32,
    pipe_retry_limit: u32,
    pipe_idle_ticks: u32,
    pipe_last_read_len: u32,
    pipe_would_block_hits: u32,
    pipe_eof_hits: u32,
    pipe_wakeup_credits: u32,
    pipe_coalesce_window: u32,
    ready_mask_seen: u8,
    ready_streak: u32,
    ready_misses: u32,
    ready_closed_hits: u32,
    ready_hup_hits: u32,
    ready_error_hits: u32,
    interest_readable_uses: u32,
    interest_writable_uses: u32,
    interest_combo_uses: u32,
    lifecycle_epoch: u64,
    lifecycle_boots: u32,
    lifecycle_shutdowns: u32,
    lifecycle_rebinds: u32,
    handle_generation: u64,
    handle_live_checks: u32,
    handle_gone_hits: u32,
    park_visits: u64,
    park_timeout_visits: u64,
    park_unpark_uses: u32,
    park_zero_timeouts: u32,
    park_long_timeouts: u32,
    dispatch_epoch: u64,
    dispatch_batches: u32,
    dispatch_empty_passes: u32,
    dispatch_overflows: u32,
    signal_family_hits: u32,
    signal_term_hits: u32,
    signal_job_hits: u32,
    signal_io_hits: u32,
    signal_child_hits: u32,
    signal_user_hits: u32,
    signal_rt_hits: u32,
    registry_slot_probes: u32,
    registry_listener_opens: u32,
    registry_broadcasts: u32,
    registry_pending_sets: u32,
    error_again_hits: u32,
