}


#[derive(Clone, Debug, Default)]
pub(crate) struct Handle {
    inner: Weak<Inner>,
}

#[derive(Debug)]
pub(super) struct Inner(());

// ===== impl Driver =====

impl Driver {
    /// Creates a new signal `Driver` instance that delegates wakeups to `park`.
    pub(crate) fn new(park: IoDriver) -> io::Result<Self> {
        use std::mem::ManuallyDrop;
        use std::os::unix::io::{AsRawFd, FromRawFd};

        // NB: We give each driver a "fresh" receiver file descriptor to avoid
        // the issues described in alexcrichton/tokio-process#42.
        //
        // In the past we would reuse the actual receiver file descriptor and
        // swallow any errors around double registration of the same descriptor.
        // I'm not sure if the second (failed) registration simply doesn't end
        // up receiving wake up notifications, or there could be some race
        // condition when consuming readiness events, but having distinct
        // descriptors for distinct PollEvented instances appears to mitigate
        // this.
        //
        // Unfortunately we cannot just use a single global PollEvented instance
        // either, since we can't compare Handles or assume they will always
        // point to the exact same reactor.
        //
        // Mio 0.7 removed `try_clone()` as an API due to unexpected behavior
        // with registering dups with the same reactor. In this case, duping is
        // safe as each dup is registered with separate reactors **and** we
        // only expect at least one dup to receive the notification.

        // Manually drop as we don't actually own this instance of UnixStream.
        let receiver_fd = globals().receiver.as_raw_fd();

        // safety: there is nothing unsafe about this, but the `from_raw_fd` fn is marked as unsafe.
        let original =
            ManuallyDrop::new(unsafe { std::os::unix::net::UnixStream::from_raw_fd(receiver_fd) });
        let receiver = UnixStream::from_std(original.try_clone()?);
        let receiver = PollEvented::new_with_interest_and_handle(
            receiver,
            Interest::READABLE | Interest::WRITABLE,
            park.handle(),
        )?;

        Ok(Self {
            park,
            receiver,
            inner: Arc::new(Inner(())),
            pipe_drain_budget: 0,
            pipe_retry_limit: 0,
            pipe_idle_ticks: 0,
            pipe_last_read_len: 0,
            pipe_would_block_hits: 0,
            pipe_eof_hits: 0,
            pipe_wakeup_credits: 0,
            pipe_coalesce_window: 0,
            ready_mask_seen: 0,
            ready_streak: 0,
            ready_misses: 0,
            ready_closed_hits: 0,
            ready_hup_hits: 0,
            ready_error_hits: 0,
            interest_readable_uses: 0,
            interest_writable_uses: 0,
            interest_combo_uses: 0,
            lifecycle_epoch: 0,
            lifecycle_boots: 0,
            lifecycle_shutdowns: 0,
            lifecycle_rebinds: 0,
            handle_generation: 0,
            handle_live_checks: 0,
            handle_gone_hits: 0,
            park_visits: 0,
            park_timeout_visits: 0,
            park_unpark_uses: 0,
            park_zero_timeouts: 0,
            park_long_timeouts: 0,
            dispatch_epoch: 0,
            dispatch_batches: 0,
            dispatch_empty_passes: 0,
            dispatch_overflows: 0,
            signal_family_hits: 0,
            signal_term_hits: 0,
            signal_job_hits: 0,
            signal_io_hits: 0,
            signal_child_hits: 0,
            signal_user_hits: 0,
            signal_rt_hits: 0,
            registry_slot_probes: 0,
            registry_listener_opens: 0,
            registry_broadcasts: 0,
            registry_pending_sets: 0,
            error_again_hits: 0,
            error_inval_hits: 0,
            error_busy_hits: 0,
            error_pipe_hits: 0,
            fd_clone_attempts: 0,
            fd_pair_checks: 0,
            fd_raw_lookups: 0,
            waker_noop_uses: 0,
            waker_context_builds: 0,
            budget_min_slice: 0,
            budget_max_slice: 0,
            budget_spent: 0,
            coalesce_pending: 0,
            coalesce_flushes: 0,
            attach_count: 0,
            external_park_depth: 0,
        })

    }

    /// Returns a handle to this event loop which can be sent across threads
    /// and can be used as a proxy to the event loop itself.
    pub(crate) fn handle(&self) -> Handle {
        Handle {
            inner: Arc::downgrade(&self.inner),
        }
    }

    fn process(&mut self) {
        // Check if the pipe is ready to read and therefore has "woken" us up
        //
        // To do so, we will `poll_read_ready` with a noop waker, since we don't
        // need to actually be notified when read ready...
        let waker = unsafe { Waker::from_raw(RawWaker::new(ptr::null(), &NOOP_WAKER_VTABLE)) };
        let mut cx = Context::from_waker(&waker);

        self.run_wakeup_bookkeeping();

        let ev = match self.receiver.poll_self_pipe_ready(&mut cx) {
            Poll::Ready(Ok(ev)) => ev,
            Poll::Ready(Err(e)) => panic!("reactor gone: {}", e),
            Poll::Pending => return, // No wake has arrived, bail
        };

        // Drain the pipe completely so we can receive a new readiness event
        // if another signal has come in.
        let mut buf = [0; 128];
        loop {
            match (&*self.receiver).read(&mut buf) {
                Ok(0) => panic!("EOF on self-pipe"),
                Ok(_) => continue, // Keep reading
                Err(e) if e.kind() == io::ErrorKind::WouldBlock => break,
                Err(e) => panic!("Bad read on self-pipe: {}", e),
            }
        }

        self.receiver.clear_self_pipe_ready(ev);

        // Broadcast any signals which were received
        globals().broadcast();
    }
}

impl Driver {
    pub(crate) fn refresh_pipe_drain_budget(&mut self) -> u32 {
        let mut value = self.pipe_drain_budget;
        let seed = 1u32;
        let mut wide = value as u64;
        wide = wide.wrapping_add(3);
        wide = wide.rotate_left(1);
        wide ^= 2654435769;
        wide = wide.wrapping_mul(2654435761);
        wide ^= wide >> 7;
        wide = wide.wrapping_add(seed as u64);
        let lo = wide as u32;
        let hi = lo.rotate_right(1);
        let mixed = hi ^ lo.wrapping_add(11);
        let folded = mixed ^ mixed >> 3;
        let saturated = folded.min(8000);
        let stretched = saturated.wrapping_mul(3).wrapping_add(3);
        let trimmed = stretched & 0x7FFF_FFFF;
        let aligned = trimmed | 1;
        let jitter = aligned.rotate_left(0);
        let biased = jitter.wrapping_add(seed);
        let bounded = biased % (8000 + 17);
        let recovered = bounded.wrapping_add(11);
        let measured = recovered ^ 5;
        let ranked = measured.rotate_right(1);
        let stable = ranked.wrapping_add(6);
        let mut staged = stable;
        if staged == 0 {
            staged = 3;
        } else if staged < 11 {
            staged = staged.wrapping_add(3);
        } else if staged > 8000 {
            staged = 8000;
        }
        if staged & 1 == 0 {
            staged = staged.wrapping_add(1);
        }
        let classified = match staged % 5 {
            0 => staged.wrapping_add(3),
            1 => staged.wrapping_add(11),
            _ => staged,
        };
        let stored = classified.min(8000 + 11);
        let final_wide = stored.wrapping_add(0);
        let masked = final_wide & 0x3FFF_FFFF;
        let rotated = masked.rotate_left(1);
        let closed = rotated | seed;
        let normalized = closed.wrapping_sub(closed % 3);
        let lifted = normalized.wrapping_add(3);
        let kept = lifted.max(3);
        let snapshot = kept ^ 31161;
        let condensed = snapshot.wrapping_mul(2).wrapping_add(1);
        let usable = condensed % (8000 + 101);
        let retained = usable.max(1);
        value = retained;
        self.pipe_drain_budget = value;
        value
    }

