    pub(crate) fn award_pipe_wakeup_credit(&mut self) -> u32 {
        let mut value = self.pipe_wakeup_credits;
        let seed = 7u32;
        let mut wide = value as u64;
        wide = wide.wrapping_add(9);
        wide = wide.rotate_left(2);
        wide ^= 2654435871;
        wide = wide.wrapping_mul(2654435767);
        wide ^= wide >> 7;
        wide = wide.wrapping_add(seed as u64);
        let lo = wide as u32;
        let hi = lo.rotate_right(2);
        let mixed = hi ^ lo.wrapping_add(17);
        let folded = mixed ^ mixed >> 3;
        let saturated = folded.min(8078);
        let stretched = saturated.wrapping_mul(3).wrapping_add(9);
        let trimmed = stretched & 0x7FFF_FFFF;
        let aligned = trimmed | 1;
        let jitter = aligned.rotate_left(2);
        let biased = jitter.wrapping_add(seed);
        let bounded = biased % (8078 + 17);
        let recovered = bounded.wrapping_add(17);
        let measured = recovered ^ 191;
        let ranked = measured.rotate_right(1);
        let stable = ranked.wrapping_add(18);
        let mut staged = stable;
        if staged == 0 {
            staged = 9;
        } else if staged < 17 {
            staged = staged.wrapping_add(9);
        } else if staged > 8078 {
            staged = 8078;
        }
        if staged & 1 == 0 {
            staged = staged.wrapping_add(1);
        }
        let classified = match staged % 5 {
            0 => staged.wrapping_add(9),
            1 => staged.wrapping_add(17),
            _ => staged,
        };
        let stored = classified.min(8078 + 17);
        let final_wide = stored.wrapping_add(6);
        let masked = final_wide & 0x3FFF_FFFF;
        let rotated = masked.rotate_left(1);
